{
  "skill_name": "code-review-and-quality",
  "trigger": {
    "positive": [
      {
        "prompt": "Review this pull request before I merge it",
        "top_k": 3
      },
      {
        "prompt": "Do a quality pass on this diff for correctness and readability",
        "top_k": 3
      },
      {
        "prompt": "Can you review the changes another model just wrote for me?",
        "top_k": 3
      }
    ],
    "negative": [
      {
        "prompt": "Deploy this to production now",
        "owner": "shipping-and-launch"
      },
      {
        "prompt": "Write a failing test for the bug before fixing it",
        "owner": "test-driven-development"
      }
    ]
  },
  "evals": [
    {
      "id": 1,
      "prompt": "Review the provided diff that adds a user-search endpoint. Deliver a structured review.",
      "expected_output": "A multi-axis review with severity-labelled findings and file:line references",
      "files": [
        "code-review-and-quality"
      ],
      "expectations": [
        "Findings cover more than one axis (correctness, readability, architecture, security, performance)",
        "Every finding carries a severity label from the skill's taxonomy",
        "Security of user input is explicitly considered for the new endpoint",
        "The review leads with high-leverage findings rather than nits"
      ]
    }
  ]
}

{
  "skill_name": "code-simplification",
  "trigger": {
    "positive": [
      {
        "prompt": "This function works but it is way too clever, simplify it without changing behavior",
        "top_k": 3
      },
      {
        "prompt": "Reduce the complexity of this module so juniors can maintain it",
        "top_k": 3
      },
      {
        "prompt": "Clean up this working code, it has grown hard to follow",
        "top_k": 3
      }
    ],
    "negative": [
      {
        "prompt": "Add a feature flag system to the app"
      },
      {
        "prompt": "Diagnose why the build broke overnight",
        "owner": "debugging-and-error-recovery"
      }
    ]
  },
  "evals": [
    {
      "id": 1,
      "prompt": "Simplify the provided 80-line function that parses config files, preserving exact behavior.",
      "expected_output": "A simpler implementation with identical behavior and a summary of what was removed and why",
      "files": [
        "code-simplification"
      ],
      "expectations": [
        "Behavior is preserved (tests unchanged and passing, or equivalence argued concretely)",
        "Complexity is reduced rather than relocated",
        "The response explains what was removed and why it was safe",
        "No new features are added during the simplification"
      ]
    }
  ]
}

{
  "skill_name": "context-engineering",
  "trigger": {
    "positive": [
      {
        "prompt": "What context should I load into the agent before starting this refactor?",
        "top_k": 3
      },
      {
        "prompt": "The model's output quality dropped mid-session, how do I fix its context?",
